class MyDataset(Dataset):
    def __init__(self, dir, transforms):
        self.img_list = ... # all image paths loaded from dir
        # do something

    def __getitem__(self, idx):
        # do something
        return data, label

    def __len__(self):
        return len(self.img_list)
